      <div class="w-12 h-12 rounded-xl bg-emerald-100 flex items-center justify-center">
        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg>
      </div>
      <h3 class="text-xl font-bold text-emerald-900">Action Steps — Build a Simple Tagging Structure</h3>
    </div>
    
    <div class="space-y-4">
      
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">1</div>
        <div>
          <p class="font-semibold text-slate-900">Review Your Current Tags</p>
          <p class="text-slate-600 text-sm">Look at tags you currently use. Are any being used for things better suited to fields, pipelines, or notes?</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">2</div>
        <div>
          <p class="font-semibold text-slate-900">Identify Misused Tags</p>
          <p class="text-slate-600 text-sm">Find tags storing details that should be custom fields, or tracking deals that should be in pipelines.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">3</div>
        <div>
          <p class="font-semibold text-slate-900">Plan Corrections</p>
          <p class="text-slate-600 text-sm">Decide which tags to keep, which to convert to other features, and which to delete.</p>
        </div>
      </div>
    </div>
  </div>
</div>',
      title = 'Understanding Tags',
      lesson_number = 1,
      sort_order = 1,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Understanding Tags';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Understanding Tags

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 12 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 12 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'understanding-tags' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson understanding-tags not found in module 12';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the main purpose of a tag?', 
    '["To store detailed contact information like budget amounts","To group contacts using a shared label for finding, filtering, and automation","To replace all other CRM features","To send emails directly without workflows"]'::jsonb,
    'To group contacts using a shared label for finding, filtering, and automation',
    'Tags are short labels that group contacts who share something in common. They help with finding, filtering, communication, and automation—but they don''t replace other CRM features like custom fields or pipelines.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where should you store a prospect''s budget information?', 
    '["In a tag like Budget-5000","In a custom field","In the contact''s first name","In a workflow name"]'::jsonb,
    'In a custom field',
    'Budget information belongs in a custom field, not a tag. Creating tags for every budget range creates too many tags and makes the list unmanageable.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where should you track a deal moving from Proposal Sent to Contract Signed?', 
    '["Using tags like STS-Proposal-Sent and STS-Contract-Signed","In the opportunity pipeline","In the contact''s email address","In a note only"]'::jsonb,
    'In the opportunity pipeline',
    'Sales deal stages belong in the opportunity pipeline, not tags. Pipelines are designed to track deals moving through defined steps with values and statuses.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
